import math

def sum_of_divisors(m):
    s = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            s += i
            if i * i != m:
                s += m // i
    return s

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

print("m | sigma(m) | Is Square?")
print("-----------------------------")
# Check up to m=50
for m in range(2, 51):
    sigma_m = sum_of_divisors(m)
    is_sq = is_square(sigma_m)
    print(f"{m:2} | {sigma_m:8} | {is_sq}")
